// Optional browser gate. Supply HTML generated by the cookbook, an installed
// Puppeteer runtime and an explicit Chrome executable. Nothing is downloaded.
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { readFile, mkdir, writeFile } from "node:fs/promises";
import { createRequire } from "node:module";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const argumentsByName = new Map();
for (let index = 2; index < process.argv.length; index += 2) {
  assert(index + 1 < process.argv.length, "each option needs a value");
  argumentsByName.set(process.argv[index], process.argv[index + 1]);
}
for (const name of ["--fixture", "--runtime-root", "--chrome", "--output"]) assert(argumentsByName.has(name), `missing ${name}`);
const root = resolve(dirname(fileURLToPath(import.meta.url)), "../..");
const fixture = await readFile(resolve(argumentsByName.get("--fixture")), "utf8");
const script = await readFile(resolve(root, "assets/code-groups.js"), "utf8");
const css = await readFile(resolve(root, "assets/code-groups.css"), "utf8");
const output = resolve(argumentsByName.get("--output"));
await mkdir(output, { recursive: true, mode: 0o700 });
const require = createRequire(resolve(argumentsByName.get("--runtime-root"), "package.json"));
const puppeteer = require("puppeteer");
const origin = "https://example.test";
const expectedCopy = "\ufeffconst x = 1;\r\n中😀\r\n";
const html = `<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/assets/code-groups.css"><title>代码组验证</title><body><h1>代码组</h1><div id="markdown-code-1-tab-0"></div>${fixture}${fixture}<script type="module">import {enhanceCodeGroups} from "/assets/code-groups.js";globalThis.enhanceCodeGroups=enhanceCodeGroups;globalThis.moduleReady=true;</script></body></html>`;
const blocked = [];
const errors = [];
const browser = await puppeteer.launch({
  executablePath: resolve(argumentsByName.get("--chrome")), headless: true, pipe: true,
  args: ["--no-sandbox", "--disable-setuid-sandbox", "--disable-dev-shm-usage", "--disable-background-networking"],
});
let result;
try {
  const context = await browser.createBrowserContext();
  await context.overridePermissions(origin, ["clipboard-read", "clipboard-sanitized-write"]);
  async function pageWithFixture(javascript) {
    const page = await context.newPage();
    await page.setJavaScriptEnabled(javascript);
    page.on("pageerror", error => errors.push(error.message));
    await page.setRequestInterception(true);
    page.on("request", request => {
      const url = request.url();
      if (url === `${origin}/`) return request.respond({ status: 200, contentType: "text/html; charset=utf-8", body: html });
      if (url === `${origin}/assets/code-groups.js`) return request.respond({ status: 200, contentType: "text/javascript; charset=utf-8", body: script });
      if (url === `${origin}/assets/code-groups.css`) return request.respond({ status: 200, contentType: "text/css; charset=utf-8", body: css });
      if (url === `${origin}/favicon.ico`) return request.respond({ status: 204, body: "" });
      blocked.push(url);
      return request.abort();
    });
    await page.goto(`${origin}/`, { waitUntil: "load" });
    return page;
  }
  const staticPage = await pageWithFixture(false);
  assert.equal(await staticPage.$$eval("figure", figures => figures.filter(figure => !figure.hidden).length), 4);
  assert.equal(await staticPage.$$eval("button", buttons => buttons.length), 0);
  assert.equal(await staticPage.$$eval("figcaption", captions => captions.map(caption => caption.textContent).join("|")), "示例😀|空块|示例😀|空块");
  await staticPage.close();
  const page = await pageWithFixture(true);
  await page.waitForFunction(() => globalThis.moduleReady === true);
  const enhanced = await page.evaluate(() => {
    const groups = document.querySelectorAll('[data-code-group="1"]');
    const unavailable = groups[1].querySelector("figure");
    unavailable.removeAttribute("data-code-copy-hex");
    unavailable.setAttribute("data-copy-unavailable", "size");
    return [enhanceCodeGroups(), enhanceCodeGroups()];
  });
  assert.deepEqual(enhanced, [2, 0]);
  assert.equal(await page.$$eval('[role="tab"]', tabs => tabs.length), 4);
  assert.equal(await page.$$eval('[role="tabpanel"]', panels => panels.filter(panel => !panel.hidden).length), 2);
  const identity = await page.evaluate(() => {
    const ids = Array.from(document.querySelectorAll("[id]"), node => node.id);
    const tabs = Array.from(document.querySelectorAll('[role="tab"]'));
    return { unique: new Set(ids).size === ids.length,
      linked: tabs.every(tab => document.getElementById(tab.getAttribute("aria-controls"))?.getAttribute("aria-labelledby") === tab.id) };
  });
  assert.deepEqual(identity, { unique: true, linked: true });
  const group = '[data-code-group="1"]';
  // Use a stable marker rather than relying on the surrounding fixture layout.
  await page.$eval(group, element => element.setAttribute("data-browser-first", "true"));
  const first = '[data-browser-first="true"]';
  await page.bringToFront();
  const capability = await page.evaluate(() => ({
    secure: isSecureContext, focused: document.hasFocus(), clipboard: typeof navigator.clipboard?.writeText,
    copies: Array.from(document.querySelectorAll('[data-browser-first="true"] .code-copy'), button => ({ disabled: button.disabled, label: button.getAttribute("aria-label") })),
  }));
  assert.equal(capability.secure, true, JSON.stringify(capability));
  assert.equal(capability.clipboard, "function", JSON.stringify(capability));
  assert.equal(capability.copies[0].disabled, false, JSON.stringify(capability));
  await page.evaluate(() => {
    const original = navigator.clipboard.writeText.bind(navigator.clipboard);
    globalThis.copyErrors = [];
    Object.defineProperty(navigator.clipboard, "writeText", { configurable: true, value: async text => {
      try { return await original(text); }
      catch (error) { globalThis.copyErrors.push({ name: error.name, message: error.message }); throw error; }
    }});
  });
  await page.click(`${first} .code-copy`);
  await page.waitForFunction(() => document.querySelector('[data-browser-first="true"] [role="status"]').textContent !== "");
  const copyState = await page.evaluate(() => ({ status: document.querySelector('[data-browser-first="true"] [role="status"]').textContent, errors: globalThis.copyErrors }));
  assert.equal(copyState.status, "已复制", JSON.stringify(copyState));
  assert.equal(await page.evaluate(() => navigator.clipboard.readText()), expectedCopy);
  await page.focus(`${first} [role="tab"]`);
  await page.keyboard.press("ArrowRight");
  assert.equal(await page.$eval(`${first} [role="tab"][aria-selected="true"]`, tab => tab.textContent), "空块");
  assert.equal(await page.evaluate(() => document.activeElement.getAttribute("aria-selected")), "true");
  await page.click(`${first} figure:not([hidden]) .code-copy`);
  await page.waitForFunction(() => document.querySelector('[data-browser-first="true"] [role="status"]').textContent === "已复制");
  assert.equal(await page.evaluate(() => navigator.clipboard.readText()), "");
  await page.focus(`${first} [role="tab"][aria-selected="true"]`);
  await page.keyboard.press("Home");
  assert.equal(await page.$eval(`${first} [role="tab"][aria-selected="true"]`, tab => tab.textContent), "示例😀");
  await page.keyboard.press("End");
  assert.equal(await page.$eval(`${first} [role="tab"][aria-selected="true"]`, tab => tab.textContent), "空块");
  await page.keyboard.press("ArrowRight");
  assert.equal(await page.$eval(`${first} [role="tab"][aria-selected="true"]`, tab => tab.textContent), "示例😀");
  assert.equal(await page.$$eval(`${group} .code-copy`, buttons => buttons.filter(button => button.disabled && button.getAttribute("aria-label") === "复制代码: 不可复制").length), 1);
  assert.equal(await page.$$eval(`${group} .code-copy:disabled`, buttons => buttons.every(button => button.textContent === "不可复制")), true);
  await page.evaluate(() => Object.defineProperty(navigator.clipboard, "writeText", {
    configurable: true, value: async () => { throw new DOMException("denied", "NotAllowedError"); },
  }));
  await page.click(`${first} figure:not([hidden]) .code-copy`);
  await page.waitForFunction(() => document.querySelector('[data-browser-first="true"] [role="status"]').textContent === "复制失败");
  assert.equal(await page.$eval(`${first} figure:not([hidden]) .code-copy`, button => button.disabled), false);
  const cdp = await page.createCDPSession();
  const accessibility = await cdp.send("Accessibility.getFullAXTree");
  const tabs = accessibility.nodes.filter(node => !node.ignored && node.role?.value?.toLowerCase() === "tab");
  assert.equal(tabs.length, 4);
  assert(tabs.every(tab => ["示例😀", "空块"].includes(tab.name.value)));
  await page.setViewport({ width: 1100, height: 850, deviceScaleFactor: 1 });
  await page.screenshot({ path: resolve(output, "code-groups-light.png"), fullPage: true });
  await page.setViewport({ width: 375, height: 850, deviceScaleFactor: 1 });
  await page.emulateMediaFeatures([{ name: "prefers-color-scheme", value: "dark" }]);
  assert(await page.evaluate(() => document.body.scrollWidth <= innerWidth));
  await page.screenshot({ path: resolve(output, "code-groups-mobile-dark.png"), fullPage: true });
  assert.deepEqual(blocked, []);
  assert.deepEqual(errors, []);
  const sha256 = text => createHash("sha256").update(text).digest("hex");
  result = { status: "PASS", node: process.version, puppeteer: require("puppeteer/package.json").version, browser: await browser.version(),
    fixtureSha256: sha256(fixture), scriptSha256: sha256(script), cssSha256: sha256(css),
    gateSha256: sha256(await readFile(fileURLToPath(import.meta.url))),
    staticFigures: 4, enhancedGroups: 2, accessibleTabs: tabs.length, rawBomUnicodeCrLfClipboard: true,
    emptyClipboard: true, keyboardAndIds: true, localizedStatusAndFailure: true,
    copyLimitFallback: true, mobileOverflow: false, unexpectedRequests: blocked.length };
  await context.close();
} finally {
  await browser.close();
}
await writeFile(resolve(output, "result.json"), JSON.stringify(result, null, 2) + "\n");
console.log(JSON.stringify(result));
